  /**
   * @method
   * @name upbit#fetchOrderBooks
   * @see https://docs.upbit.com/kr/reference/list-orderbooks
   * @see https://global-docs.upbit.com/reference/list-orderbooks
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data for multiple markets
   * @param {string[]|undefined} symbols list of unified market symbols, all
   * symbols fetched if undefined, default is undefined
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [order book structures]{@link
   * https://docs.ccxt.com/?id=order-book-structure} indexed by market symbol
   */
  std::shared_future<ccxt::any>
  fetchOrderBooks(ccxt::any symbols = ccxt::any{},
                  ccxt::any limit = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any ids = ccxt::any{};
                 if (isTrue(isEqual(symbols, ccxt::any{}))) {
                   ccxt::any allIds = this->ids;
                   if (isTrue(!isEqual(allIds, ccxt::any{}))) {
                     ids = join(allIds, std::string(","));
                   }
                 } else {
                   ccxt::any marketIds = this->marketIds(symbols);
                   ids = join(marketIds, std::string(","));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("markets"), ids},
                 };
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("count"), limit);
                 }
                 ccxt::any response = awaitValue(
                     this->publicGetOrderbook(this->extend(request, params)));
                 //
                 //     [ {          market:   "BTC-ETH",
                 //               "timestamp":    1542899030043,
                 //          "total_ask_size":    109.57065201,
                 //          "total_bid_size":    125.74430631,
                 //         "orderbook_units": [ { ask_price: 0.02926679,
                 //                              "bid_price": 0.02919904,
                 //                               "ask_size": 4.20293961,
                 //                               "bid_size": 11.65043576 },
                 //                            ...,
                 //                            { ask_price: 0.02938209,
                 //                              "bid_price": 0.0291231,
                 //                               "ask_size": 0.05135782,
                 //                               "bid_size": 13.5595     }   ]
                 //                               },
                 //       {          market:   "KRW-BTC",
                 //               "timestamp":    1542899034662,
                 //          "total_ask_size":    12.89790974,
                 //          "total_bid_size":    4.88395783,
                 //         "orderbook_units": [ { ask_price: 5164000,
                 //                              "bid_price": 5162000,
                 //                               "ask_size": 2.57606495,
                 //                               "bid_size": 0.214       },
                 //                            ...,
                 //                            { ask_price: 5176000,
                 //                              "bid_price": 5152000,
                 //                               "ask_size": 2.752,
                 //                               "bid_size": 0.4650305 }    ] }
                 //                               ]
                 //
                 ccxt::any result = ccxt::dict{};
                 ccxt::any orderbooks = this->toArray(response);
                 for (ccxt::any i = 0;
                      isLessThan(i, getArrayLength(orderbooks));
                      postFixIncrement(i)) {
                   ccxt::any orderbook = ::getValue(orderbooks, i);
                   ccxt::any marketId =
                       this->safeString(orderbook, std::string("market"));
                   ccxt::any symbol = this->safeSymbol(marketId, ccxt::any{},
                                                       std::string("-"));
                   ccxt::any timestamp =
                       this->safeInteger(orderbook, std::string("timestamp"));
                   ::setValue(
                       result, symbol,
                       ccxt::dict{
                           {std::string("symbol"), symbol},
                           {std::string("bids"),
                            this->sortBy(
                                this->parseOrderBookBidsAsks(
                                    ::getValue(orderbook,
                                               std::string("orderbook_units")),
                                    std::string("bid_price"),
                                    std::string("bid_size")),
                                0, true)},
                           {std::string("asks"),
                            this->sortBy(
                                this->parseOrderBookBidsAsks(
                                    ::getValue(orderbook,
                                               std::string("orderbook_units")),
                                    std::string("ask_price"),
                                    std::string("ask_size")),
                                0)},
                           {std::string("timestamp"), timestamp},
                           {std::string("datetime"), this->iso8601(timestamp)},
                           {std::string("nonce"), ccxt::any{}},
                       });
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name upbit#fetchOrderBook
   * @see https://docs.upbit.com/kr/reference/list-orderbooks
   * @see https://global-docs.upbit.com/reference/list-orderbooks
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any orderbooks = awaitValue(this->fetchOrderBooks(
                            ccxt::list{symbol}, limit, params));
                        return this->safeValue(orderbooks, symbol);
                      })
        .share();
  }

  ccxt::any parseTicker(ccxt::any ticker,
                        ccxt::any market = ccxt::any{}) override {
    //
    //       {                market: "BTC-ETH",
    //                    "trade_date": "20181122",
    //                    "trade_time": "104543",
    //                "trade_date_kst": "20181122",
    //                "trade_time_kst": "194543",
    //               "trade_timestamp":  1542883543096,
    //                 "opening_price":  0.02976455,
    //                    "high_price":  0.02992577,
    //                     "low_price":  0.02934283,
    //                   "trade_price":  0.02947773,
    //            "prev_closing_price":  0.02966,
    //                        "change": "FALL",
    //                  "change_price":  0.00018227,
    //                   "change_rate":  0.0061453136,
    //           "signed_change_price":  -0.00018227,
    //            "signed_change_rate":  -0.0061453136,
    //                  "trade_volume":  1.00000005,
    //               "acc_trade_price":  100.95825586,
    //           "acc_trade_price_24h":  289.58650166,
    //              "acc_trade_volume":  3409.85311036,
    //          "acc_trade_volume_24h":  9754.40510513,
    //         "highest_52_week_price":  0.12345678,
    //          "highest_52_week_date": "2018-02-01",
    //          "lowest_52_week_price":  0.023936,
    //           "lowest_52_week_date": "2017-12-08",
    //                     "timestamp":  1542883543813  }
    //
    ccxt::any timestamp =
        this->safeInteger(ticker, std::string("trade_timestamp"));
    ccxt::any marketId =
        this->safeString2(ticker, std::string("market"), std::string("code"));
    market = this->safeMarket(marketId, market, std::string("-"));
    ccxt::any last = this->safeString(ticker, std::string("trade_price"));
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("high"),
             this->safeString(ticker, std::string("high_price"))},
            {std::string("low"),
             this->safeString(ticker, std::string("low_price"))},
            {std::string("bid"), ccxt::any{}},
            {std::string("bidVolume"), ccxt::any{}},
            {std::string("ask"), ccxt::any{}},
            {std::string("askVolume"), ccxt::any{}},
            {std::string("vwap"), ccxt::any{}},
            {std::string("open"),
             this->safeString(ticker, std::string("opening_price"))},
            {std::string("close"), last},
            {std::string("last"), last},
            {std::string("previousClose"),
             this->safeString(ticker, std::string("prev_closing_price"))},
            {std::string("change"),
             this->safeString(ticker, std::string("signed_change_price"))},
            {std::string("percentage"),
             ccxt::Precise::stringMul(
                 this->safeString(ticker, std::string("signed_change_rate")),
                 std::string("100"))},
            {std::string("average"), ccxt::any{}},
            {std::string("baseVolume"),
             this->safeString(ticker, std::string("acc_trade_volume_24h"))},
            {std::string("quoteVolume"),
             this->safeString(ticker, std::string("acc_trade_price_24h"))},
            {std::string("info"), ticker},
        },
        market);
  }

  /**
   * @method
   * @name upbit#fetchTickers
   * @see https://docs.upbit.com/kr/reference/list-tickers
   * @see https://global-docs.upbit.com/reference/list-tickers
   * @see https://docs.upbit.com/kr/reference/tickers_by_quote
   * @see https://global-docs.upbit.com/reference/tickers_by_quote
   * @description fetches price tickers for multiple markets, statistical
   * information calculated over the past 24 hours for each market
   * @param {string[]|undefined} symbols unified symbols of the markets to fetch
   * the ticker for, all market tickers are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.quote_currencies] comma-separated quote currency
   * ids to fetch all tickers for, defaults to every quote currency of the
   * loaded markets, only used when symbols is undefined
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTickers(ccxt::any symbols = ccxt::any{},
               ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 symbols = this->marketSymbols(symbols);
                 ccxt::any tickers = ccxt::list{};
                 if (isTrue(isEqual(symbols, ccxt::any{}))) {
                   // ticker/all returns every market of the requested quote
                   // currencies with a single request
                   ccxt::any quoteIds = ccxt::list{};
                   ccxt::any marketSymbols = this->symbols;
                   for (ccxt::any i = 0;
                        isLessThan(i, getArrayLength(marketSymbols));
                        postFixIncrement(i)) {
                     ccxt::any market =
                         this->market(::getValue(marketSymbols, i));
                     ccxt::any quoteId =
                         ::getValue(market, std::string("quoteId"));
                     if (!isTrue(this->inArray(quoteId, quoteIds))) {
                       arrayPush(quoteIds, quoteId);
                     }
                   }
                   ccxt::any sortedQuoteIds = this->sort(
                       quoteIds); // market iteration order differs per language
                   ccxt::any quoteCurrencies = std::string("");
                   for (ccxt::any i = 0;
                        isLessThan(i, getArrayLength(sortedQuoteIds));
                        postFixIncrement(i)) {
                     if (isTrue(!isEqual(quoteCurrencies, std::string("")))) {
                       quoteCurrencies = add(quoteCurrencies, std::string(","));
                     }
                     quoteCurrencies =
                         add(quoteCurrencies, ::getValue(sortedQuoteIds, i));
                   }
                   ccxt::any request = ccxt::dict{
                       {std::string("quote_currencies"), quoteCurrencies},
                   };
                   tickers = awaitValue(
                       this->publicGetTickerAll(this->extend(request, params)));
                 } else {
                   ccxt::any ids = this->marketIds(symbols);
                   ccxt::any promises = ccxt::list{};
                   ccxt::any queries = this->idsQueryStrings(
                       ids,
                       4000); // the url is limited to about 8000 characters
                              // once the commas are percent-encoded
                   for (ccxt::any i = 0; isLessThan(i, getArrayLength(queries));
                        postFixIncrement(i)) {
                     ccxt::any idsQuery = ::getValue(queries, i);
                     arrayPush(promises,
                               this->publicGetTicker(this->extend(
                                   ccxt::dict{
                                       {std::string("markets"), idsQuery},
                                   },
                                   params)));
                   }
                   ccxt::any responses = awaitValue(promiseAll(promises));
                   tickers = this->arraysConcat(responses);
                 }
                 //
                 //     [ {                market: "BTC-ETH",
                 //                    "trade_date": "20181122",
                 //                    "trade_time": "104543",
                 //                "trade_date_kst": "20181122",
                 //                "trade_time_kst": "194543",
                 //               "trade_timestamp":  1542883543097,
                 //                 "opening_price":  0.02976455,
                 //                    "high_price":  0.02992577,
                 //                     "low_price":  0.02934283,
                 //                   "trade_price":  0.02947773,
                 //            "prev_closing_price":  0.02966,
                 //                        "change": "FALL",
                 //                  "change_price":  0.00018227,
                 //                   "change_rate":  0.0061453136,
                 //           "signed_change_price":  -0.00018227,
                 //            "signed_change_rate":  -0.0061453136,
                 //                  "trade_volume":  1.00000005,
                 //               "acc_trade_price":  100.95825586,
                 //           "acc_trade_price_24h":  289.58650166,
                 //              "acc_trade_volume":  3409.85311036,
                 //          "acc_trade_volume_24h":  9754.40510513,
                 //         "highest_52_week_price":  0.12345678,
                 //          "highest_52_week_date": "2018-02-01",
                 //          "lowest_52_week_price":  0.023936,
                 //           "lowest_52_week_date": "2017-12-08",
                 //                     "timestamp":  1542883543813  } ]
                 //
                 return this->parseTickers(tickers, symbols);
               })
        .share();
  }

  virtual ccxt::any idsQueryStrings(ccxt::any ids, ccxt::any maxQueryLength) {
    if (isTrue(isEqual(ids, ccxt::any{}))) {
      return ccxt::list{};
    }
    ccxt::any idsString = std::string("");
    ccxt::any queries = ccxt::list{};
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(ids));
         postFixIncrement(i)) {
      ccxt::any id = ::getValue(ids, i);
      if (isTrue(!isEqual(idsString, std::string("")))) {
        idsString = add(idsString, std::string(","));
      }
      idsString = add(idsString, id);
      if (isTrue(isGreaterThanOrEqual(getStringLength(idsString),
                                      maxQueryLength))) {
        arrayPush(queries, idsString);
        idsString = std::string("");
      }
    }
    if (isTrue(!isEqual(idsString, std::string("")))) {
      arrayPush(queries, idsString);
    }
    return queries;
  }

  /**
   * @method
   * @name upbit#fetchTicker
   * @see https://docs.upbit.com/kr/reference/list-tickers
   * @see https://global-docs.upbit.com/reference/list-tickers
   * @description fetches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for a specific market
   * @param {string} symbol unified symbol of the market to fetch the ticker for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTicker(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any tickers = awaitValue(
                            this->fetchTickers(ccxt::list{symbol}, params));
                        return this->safeValue(tickers, symbol);
                      })
        .share();
  }

  ccxt::any parseTrade(ccxt::any trade,
                       ccxt::any market = ccxt::any{}) override {
    //
    // fetchTrades
    //
    //       {             market: "BTC-ETH",
    //             "trade_date_utc": "2018-11-22",
    //             "trade_time_utc": "13:55:24",
    //                  "timestamp":  1542894924397,
    //                "trade_price":  0.02914289,
    //               "trade_volume":  0.20074397,
    //         "prev_closing_price":  0.02966,
    //               "change_price":  -0.00051711,
    //                    "ask_bid": "ASK",
    //              "sequential_id":  15428949259430000 }
    //
    // fetchOrder trades
    //
    //         {
    //             "market": "KRW-BTC",
    //             "uuid": "78162304-1a4d-4524-b9e6-c9a9e14d76c3",
    //             "price": "101000.0",
    //             "volume": "0.77368323",
    //             "funds": "78142.00623",
    //             "ask_fee": "117.213009345",
    //             "bid_fee": "117.213009345",
    //             "created_at": "2018-04-05T14:09:15+09:00",
    //             "side": "bid",
    //         }
    //
    ccxt::any id = this->safeString2(trade, std::string("sequential_id"),
                                     std::string("uuid"));
    ccxt::any orderId = ccxt::any{};
    ccxt::any timestamp = this->safeInteger(trade, std::string("timestamp"));
    if (isTrue(isEqual(timestamp, ccxt::any{}))) {
      timestamp =
          this->parse8601(this->safeString(trade, std::string("created_at")));
    }
    ccxt::any side = ccxt::any{};
    ccxt::any askOrBid = this->safeStringLower2(trade, std::string("ask_bid"),
                                                std::string("side"));
    if (isTrue(isEqual(askOrBid, std::string("ask")))) {
      side = std::string("sell");
    } else if (isTrue(isEqual(askOrBid, std::string("bid")))) {
      side = std::string("buy");
    }
    ccxt::any cost = this->safeString(trade, std::string("funds"));
    ccxt::any price = this->safeString2(trade, std::string("trade_price"),
                                        std::string("price"));
    ccxt::any amount = this->safeString2(trade, std::string("trade_volume"),
                                         std::string("volume"));
    ccxt::any marketId =
        this->safeString2(trade, std::string("market"), std::string("code"));
    market = this->safeMarket(marketId, market, std::string("-"));
    ccxt::any fee = ccxt::any{};
    ccxt::any feeCost =
        this->safeString(trade, add(askOrBid, std::string("_fee")));
    if (isTrue(!isEqual(feeCost, ccxt::any{}))) {
      fee = ccxt::dict{
          {std::string("currency"), ::getValue(market, std::string("quote"))},
          {std::string("cost"), feeCost},
      };
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("id"), id},
            {std::string("info"), trade},
            {std::string("order"), orderId},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("type"), ccxt::any{}},
            {std::string("side"), side},
            {std::string("takerOrMaker"), ccxt::any{}},
            {std::string("price"), price},
            {std::string("amount"), amount},
            {std::string("cost"), cost},
            {std::string("fee"), fee},
        },
        market);
  }

  /**
   * @method
   * @name upbit#fetchTrades
   * @see https://docs.upbit.com/kr/reference/list-pair-trades
   * @see https://global-docs.upbit.com/reference/list-pair-trades
   * @description get the list of most recent trades for a particular symbol
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch
   * @param {int} [limit] the maximum amount of trades to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<ccxt::any>
  fetchTrades(ccxt::any symbol, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 if (isTrue(isEqual(limit, ccxt::any{}))) {
                   limit = 200;
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                     {std::string("count"), limit},
                 };
                 ccxt::any response = awaitValue(
                     this->publicGetTradesTicks(this->extend(request, params)));
                 //
                 //     [ {             market: "BTC-ETH",
                 //             "trade_date_utc": "2018-11-22",
                 //             "trade_time_utc": "13:55:24",
                 //                  "timestamp":  1542894924397,
                 //                "trade_price":  0.02914289,
                 //               "trade_volume":  0.20074397,
                 //         "prev_closing_price":  0.02966,
                 //               "change_price":  -0.00051711,
                 //                    "ask_bid": "ASK",
                 //              "sequential_id":  15428949259430000 },
                 //       {             market: "BTC-ETH",
                 //             "trade_date_utc": "2018-11-22",
                 //             "trade_time_utc": "13:03:10",
                 //                  "timestamp":  1542891790123,
                 //                "trade_price":  0.02917,
                 //               "trade_volume":  7.392,
                 //         "prev_closing_price":  0.02966,
                 //               "change_price":  -0.00049,
                 //                    "ask_bid": "ASK",
                 //              "sequential_id":  15428917910540000 }  ]
                 //
                 return this->parseTrades(response, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name upbit#fetchTradingFee
   * @see https://docs.upbit.com/kr/reference/available-order-information
   * @see https://global-docs.upbit.com/reference/available-order-information
   * @description fetch the trading fees for a market
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [fee structure]{@link
   * https://docs.ccxt.com/?id=fee-structure}
   */
  std::shared_future<ccxt::any>
  fetchTradingFee(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                 };
                 ccxt::any response = awaitValue(this->privateGetOrdersChance(
                     this->extend(request, params)));
                 //
                 //     {
                 //         "bid_fee": "0.0005",
                 //         "ask_fee": "0.0005",
                 //         "maker_bid_fee": "0.0005",
                 //         "maker_ask_fee": "0.0005",
                 //         "market": {
                 //             "id": "KRW-BTC",
                 //             "name": "BTC/KRW",
                 //             "order_types": [ "limit" ],
                 //             "order_sides": [ "ask", "bid" ],
                 //             "bid": { "currency": "KRW", "price_unit": null,
                 //             "min_total": 5000 }, "ask": { "currency": "BTC",
                 //             "price_unit": null, "min_total": 5000 },
                 //             "max_total": "1000000000.0",
                 //             "state": "active"
                 //         },
                 //         "bid_account": {
                 //             "currency": "KRW",
                 //             "balance": "0.34202415",
                 //             "locked": "4999.99999922",
                 //             "avg_buy_price": "0",
                 //             "avg_buy_price_modified": true,
                 //             "unit_currency": "KRW"
                 //         },
                 //         "ask_account": {
                 //             "currency": "BTC",
                 //             "balance": "0.00048",
                 //             "locked": "0.0",
                 //             "avg_buy_price": "20870000",
                 //             "avg_buy_price_modified": false,
                 //             "unit_currency": "KRW"
                 //         }
                 //     }
                 //
                 ccxt::any askFee =
                     this->safeString(response, std::string("ask_fee"));
                 ccxt::any bidFee =
                     this->safeString(response, std::string("bid_fee"));
                 ccxt::any taker = ccxt::Precise::stringMax(askFee, bidFee);
                 ccxt::any makerAskFee =
                     this->safeString(response, std::string("maker_ask_fee"));
                 ccxt::any makerBidFee =
                     this->safeString(response, std::string("maker_bid_fee"));
                 ccxt::any maker =
                     ccxt::Precise::stringMax(makerAskFee, makerBidFee);
                 return ccxt::dict{
                     {std::string("info"), response},
                     {std::string("symbol"), symbol},
                     {std::string("maker"), this->parseNumber(maker)},
                     {std::string("taker"), this->parseNumber(taker)},
                     {std::string("percentage"), true},
                     {std::string("tierBased"), false},
                 };
               })
        .share();
  }

  /**
   * @method
   * @name upbit#fetchTradingFees
   * @description fetch the trading fees for markets
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [trading fee structure]{@link
   * https://docs.ccxt.com/?id=trading-fee-structure}
   */
  std::shared_future<ccxt::any>
  fetchTradingFees(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any fetchMarketResponse =
                     awaitValue(this->fetchMarkets(params));
                 ccxt::any response = ccxt::dict{};
                 for (ccxt::any i = 0;
                      isLessThan(i, getArrayLength(fetchMarketResponse));
                      postFixIncrement(i)) {
                   ccxt::any element = ccxt::dict{};
                   ::setValue(
                       element, std::string("maker"),
                       this->safeNumber(::getValue(fetchMarketResponse, i),
                                        std::string("maker")));
                   ::setValue(
                       element, std::string("taker"),
                       this->safeNumber(::getValue(fetchMarketResponse, i),
                                        std::string("taker")));
                   ::setValue(
                       element, std::string("symbol"),
                       this->safeString(::getValue(fetchMarketResponse, i),
                                        std::string("symbol")));
                   ::setValue(element, std::string("percentage"), true);
                   ::setValue(element, std::string("tierBased"), false);
                   ::setValue(element, std::string("info"),
                              ::getValue(fetchMarketResponse, i));
                   ccxt::any feeSymbol =
                       this->safeString(::getValue(fetchMarketResponse, i),
                                        std::string("symbol"));
                   if (isTrue(!isEqual(feeSymbol, ccxt::any{}))) {
                     ::setValue(response, feeSymbol, element);
                   }
                 }
                 return response;
               })
        .share();
  }

  ccxt::any parseOHLCV(ccxt::any ohlcv,
                       ccxt::any market = ccxt::any{}) override {
    //
    //     {
    //         "market": "BTC-ETH",
    //         "candle_date_time_utc": "2018-11-22T13:47:00",
    //         "candle_date_time_kst": "2018-11-22T22:47:00",
    //         "opening_price": 0.02915963,
    //         "high_price": 0.02915963,
    //         "low_price": 0.02915448,
    //         "trade_price": 0.02915448,
    //         "timestamp": 1542894473674,
    //         "candle_acc_trade_price": 0.0981629437535248,
    //         "candle_acc_trade_volume": 3.36693173,
    //         "unit": 1
    //     }
    //
    return ccxt::list{
        this->parse8601(
            this->safeString(ohlcv, std::string("candle_date_time_utc"))),
        this->safeNumber(ohlcv, std::string("opening_price")),
        this->safeNumber(ohlcv, std::string("high_price")),
        this->safeNumber(ohlcv, std::string("low_price")),
        this->safeNumber(ohlcv, std::string("trade_price")),
        this->safeNumber(ohlcv, std::string("candle_acc_trade_volume"))};
  }

  /**
   * @method
   * @name upbit#fetchOHLCV
   * @see https://docs.upbit.com/kr/reference/list-candles-minutes
   * @see https://global-docs.upbit.com/reference/list-candles-minutes
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<ccxt::any>
  fetchOHLCV(ccxt::any symbol, ccxt::any timeframe = std::string("1m"),
             ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any timeframePeriod = this->parseTimeframe(timeframe);
                 ccxt::any timeframeValue =
                     this->safeString(this->timeframes, timeframe, timeframe);
                 if (isTrue(isEqual(limit, ccxt::any{}))) {
                   limit = 200;
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                     {std::string("timeframe"), timeframeValue},
                     {std::string("count"), limit},
                 };
                 ccxt::any response = ccxt::any{};
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   // convert `since` to `to` value
                   ::setValue(
                       request, std::string("to"),
                       this->iso8601(this->sum(
                           since,
                           multiply(multiply(timeframePeriod, limit), 1000))));
                 }
                 if (isTrue(isEqual(timeframeValue, std::string("minutes")))) {
                   ccxt::any numMinutes =
                       mathRound(divide(timeframePeriod, 60));
                   ::setValue(request, std::string("unit"), numMinutes);
                   response = awaitValue(this->publicGetCandlesTimeframeUnit(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->publicGetCandlesTimeframe(
                       this->extend(request, params)));
                 }
                 //
                 //     [
                 //         {
                 //             "market": "BTC-ETH",
                 //             "candle_date_time_utc": "2018-11-22T13:47:00",
                 //             "candle_date_time_kst": "2018-11-22T22:47:00",
                 //             "opening_price": 0.02915963,
                 //             "high_price": 0.02915963,
                 //             "low_price": 0.02915448,
                 //             "trade_price": 0.02915448,
                 //             "timestamp": 1542894473674,
                 //             "candle_acc_trade_price": 0.0981629437535248,
                 //             "candle_acc_trade_volume": 3.36693173,
                 //             "unit": 1
                 //         },
                 //         {
                 //             "market": "BTC-ETH",
                 //             "candle_date_time_utc": "2018-11-22T10:06:00",
                 //             "candle_date_time_kst": "2018-11-22T19:06:00",
                 //             "opening_price": 0.0294,
                 //             "high_price": 0.02940882,
                 //             "low_price": 0.02934283,
                 //             "trade_price": 0.02937354,
                 //             "timestamp": 1542881219276,
                 //             "candle_acc_trade_price": 0.0762597110943884,
                 //             "candle_acc_trade_volume": 2.5949617,
                 //             "unit": 1
                 //         }
                 //     ]
                 //
                 ccxt::any ohlcvs = this->toArray(response);
                 return this->parseOHLCVs(ohlcvs, market, timeframe, since,
                                          limit);
               })
        .share();
  }

  virtual ccxt::any calcOrderPrice(ccxt::any symbol, ccxt::any amount,
                                   ccxt::any price = ccxt::any{},
                                   ccxt::any params = ccxt::dict{}) {
    ccxt::any quoteAmount = ccxt::any{};
    ccxt::any createMarketBuyOrderRequiresPrice = this->safeValue(
        this->options, std::string("createMarketBuyOrderRequiresPrice"));
    ccxt::any cost = this->safeString(params, std::string("cost"));
    if (isTrue(!isEqual(cost, ccxt::any{}))) {
      quoteAmount = this->costToPrecision(symbol, cost);
    } else if (isTrue(isEqual(createMarketBuyOrderRequiresPrice, true))) {
      if (isTrue(isTrue(isEqual(price, ccxt::any{})) ||
                 isTrue(isEqual(amount, ccxt::any{})))) {
        throw InvalidOrder(toString(add(
            this->id,
            std::string(" createOrder() requires the price and amount argument "
                        "for market buy orders to calculate the total cost to "
                        "spend (amount * price), alternatively set the "
                        "createMarketBuyOrderRequiresPrice option or param to "
                        "false and pass the cost to spend (quote quantity) in "
                        "the amount argument"))));
      }
      ccxt::any amountString = this->numberToString(amount);
      ccxt::any priceString = this->numberToString(price);
      ccxt::any costRequest =
          ccxt::Precise::stringMul(amountString, priceString);
      quoteAmount = this->costToPrecision(symbol, costRequest);
    } else {
      if (isTrue(isEqual(amount, ccxt::any{}))) {
        throw ArgumentsRequired(toString(add(
            this->id, std::string(" When createMarketBuyOrderRequiresPrice is "
                                  "false, \"amount\" is required and should be "
                                  "the total quote amount to spend."))));
      }
      quoteAmount = this->costToPrecision(symbol, amount);
    }
    if (isTrue(isEqual(quoteAmount, ccxt::any{}))) {
      throw ArgumentsRequired(toString(add(
          this->id,
          std::string(" calcOrderPrice() could not determine quote amount"))));
    }
    return quoteAmount;
  }

  /**
   * @method
   * @name upbit#createOrder
   * @description create a trade order
   * @see https://docs.upbit.com/kr/reference/new-order
   * @see https://global-docs.upbit.com/reference/new-order
   * @see https://docs.upbit.com/kr/reference/order-test
   * @see https://global-docs.upbit.com/reference/order-test
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type supports 'market' and 'limit'. if params.ordType is
   * set to best, a best-type order will be created regardless of the value of
   * type.
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much you want to trade in units of the base
   * currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {float} [params.cost] for market buy and best buy orders, the quote
   * quantity that can be used as an alternative for the amount
   * @param {string} [params.ordType] this field can be used to place a ‘best’
   * type order
   * @param {string} [params.timeInForce] 'IOC' or 'FOK' for limit or best type
   * orders, 'PO' for limit orders. this field is required when the order type
   * is 'best'.
   * @param {string} [params.selfTradePrevention] 'reduce', 'cancel_maker',
   * 'cancel_taker' {@link https://global-docs.upbit.com/docs/smp}
   * @param {boolean} [params.test] If test is true, testOrder will be executed.
   * It allows you to validate the request without creating an actual order.
   * Default is false.
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createOrder(ccxt::any symbol, ccxt::any type, ccxt::any side,
              ccxt::any amount, ccxt::any price = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any clientOrderId =
                     this->safeString(params, std::string("clientOrderId"));
                 ccxt::any customType = this->safeString2(
                     params, std::string("ordType"), std::string("ord_type"));
                 ccxt::any postOnly = this->isPostOnly(
                     isEqual(type, std::string("market")), false, params);
                 ccxt::any timeInForce =
                     this->safeStringLower2(params, std::string("timeInForce"),
                                            std::string("time_in_force"));
                 ccxt::any selfTradePrevention = this->safeString2(
                     params, std::string("selfTradePrevention"),
                     std::string("smp_type"));
                 ccxt::any test =
                     this->safeBool(params, std::string("test"), false);
                 if (isTrue(isTrue(postOnly) &&
                            isTrue((
                                !isEqual(selfTradePrevention, ccxt::any{}))))) {
                   throw ExchangeError(toString(
                       add(this->id,
                           std::string(
                               " createOrder() does not support post_only and "
                               "selfTradePrevention simultaneously."))));
                 }
                 ccxt::any orderSide = ccxt::any{};
                 if (isTrue(isEqual(side, std::string("buy")))) {
                   orderSide = std::string("bid");
                 } else if (isTrue(isEqual(side, std::string("sell")))) {
                   orderSide = std::string("ask");
                 } else {
                   throw InvalidOrder(toString(
                       add(this->id,
                           std::string(" createOrder() supports only buy or "
                                       "sell in the side argument."))));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                     {std::string("side"), orderSide},
                 };
                 if (isTrue(isEqual(type, std::string("limit")))) {
                   if (isTrue(isTrue(isEqual(price, ccxt::any{})) ||
                              isTrue(isEqual(amount, ccxt::any{})))) {
                     throw ArgumentsRequired(toString(add(
                         this->id,
                         std::string(" the limit type order in createOrder() "
                                     "is required price and amount."))));
                   }
                   ::setValue(request, std::string("ord_type"),
                              std::string("limit"));
                   ::setValue(request, std::string("price"),
                              this->priceToPrecision(symbol, price));
                   ::setValue(request, std::string("volume"),
                              this->amountToPrecision(symbol, amount));
                 } else if (isTrue(isEqual(type, std::string("market")))) {
                   if (isTrue(isEqual(side, std::string("buy")))) {
                     ::setValue(request, std::string("ord_type"),
                                std::string("price"));
                     ccxt::any orderPrice =
                         this->calcOrderPrice(symbol, amount, price, params);
                     ::setValue(request, std::string("price"), orderPrice);
                   } else {
                     if (isTrue(isEqual(amount, ccxt::any{}))) {
                       throw ArgumentsRequired(toString(add(
                           this->id,
                           std::string(" the market sell type order in "
                                       "createOrder() is required amount."))));
                     }
                     ::setValue(request, std::string("ord_type"),
                                std::string("market"));
                     ::setValue(request, std::string("volume"),
                                this->amountToPrecision(symbol, amount));
                   }
                 } else {
                   throw InvalidOrder(toString(
                       add(this->id,
                           std::string(" createOrder() supports only limit or "
                                       "market types in the type argument."))));
                 }
                 if (isTrue(isEqual(customType, std::string("best")))) {
                   params =
                       this->omit(params, ccxt::list{std::string("ordType"),
                                                     std::string("ord_type")});
                   ::setValue(request, std::string("ord_type"),
                              std::string("best"));
                   if (isTrue(isEqual(side, std::string("buy")))) {
                     ccxt::any orderPrice =
                         this->calcOrderPrice(symbol, amount, price, params);
                     ::setValue(request, std::string("price"), orderPrice);
                   } else {
                     if (isTrue(isEqual(amount, ccxt::any{}))) {
                       throw ArgumentsRequired(toString(add(
                           this->id,
                           std::string(" the best sell type order in "
                                       "createOrder() is required amount."))));
                     }
                     ::setValue(request, std::string("volume"),
                                this->amountToPrecision(symbol, amount));
                   }
                 }
                 if (isTrue(!isEqual(clientOrderId, ccxt::any{}))) {
                   ::setValue(request, std::string("identifier"),
                              clientOrderId);
                 }
                 if (isTrue(postOnly)) {
                   if (isTrue(!isEqual(
                           ::getValue(request, std::string("ord_type")),
                           std::string("limit")))) {
                     throw InvalidOrder(toString(add(
                         this->id, std::string(" postOnly orders are only "
                                               "supported for limit orders"))));
                   }
                   ::setValue(request, std::string("time_in_force"),
                              std::string("post_only"));
                 }
                 if (isTrue(!isEqual(timeInForce, ccxt::any{}))) {
                   if (isTrue(
                           isTrue(isEqual(timeInForce, std::string("ioc"))) ||
                           isTrue(isEqual(timeInForce, std::string("fok"))))) {
                     ::setValue(request, std::string("time_in_force"),
                                timeInForce);
                   }
                 }
                 if (isTrue(isTrue(isEqual(
                                ::getValue(request, std::string("ord_type")),
                                std::string("best"))) &&
                            isTrue(isEqual(timeInForce, ccxt::any{})))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(" createOrder() requires a timeInForce "
                                       "parameter for best type orders"))));
                 }
                 ccxt::any response = ccxt::any{};
                 params = this->omit(
                     params,
                     ccxt::list{
                         std::string("timeInForce"),
                         std::string("time_in_force"), std::string("postOnly"),
                         std::string("clientOrderId"), std::string("cost"),
                         std::string("selfTradePrevention"),
                         std::string("smp_type"), std::string("test")});
                 if (isTrue(isEqual(test, true))) {
                   response = awaitValue(this->privatePostOrdersTest(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(
                       this->privatePostOrders(this->extend(request, params)));
                 }
                 //
                 //     {
                 //         "uuid": "cdd92199-2897-4e14-9448-f923320408ad",
                 //         "side": "bid",
                 //         "ord_type": "limit",
                 //         "price": "100.0",
                 //         "avg_price": "0.0",
                 //         "state": "wait",
                 //         "market": "KRW-BTC",
                 //         "created_at": "2018-04-10T15:42:23+09:00",
                 //         "volume": "0.01",
                 //         "remaining_volume": "0.01",
                 //         "reserved_fee": "0.0015",
                 //         "remaining_fee": "0.0015",
                 //         "paid_fee": "0.0",
                 //         "locked": "1.0015",
                 //         "executed_volume": "0.0",
                 //         "trades_count": 0
                 //     }
                 //
                 return this->parseOrder(response);
               })
        .share();
  }

