                        //         "locked": "17341974.0",
                        //         "executed_volume": "1.0",
                        //         "trades_count": 2,
                        //         "trades": [
                        //             {
                        //                 "market": "KRW-BTC",
                        //                 "uuid":
                        //                 "78162304-1a4d-4524-b9e6-c9a9e14d76c3",
                        //                 "price": "101000.0",
                        //                 "volume": "0.77368323",
                        //                 "funds": "78142.00623",
                        //                 "ask_fee": "117.213009345",
                        //                 "bid_fee": "117.213009345",
                        //                 "created_at":
                        //                 "2018-04-05T14:09:15+09:00", "side":
                        //                 "bid"
                        //             },
                        //             {
